ul.li:
          on_same_line - The right curly brace must be on the same line as the
          previous part of the expression:


String[] names = new String[] {"One", "Two", };
Runnable action = () -> { doSomething(); };

          on_new_line - The right curly brace must be on a new line:


String[] names = new String[] {"One", "Two",
};
Runnable action = () -> { doSomething();
};

          on_new_line_or_singleline - The right curly brace must be on a new line,
          unless the whole expression block is on a single line:


// Single-line format of block
String[] names = new String[] {"One", "Two", };

// Multi-line format of block
String[] names = new String[] {"One", "Two",
};

pre.code:
class Example1 {

  String[] oneLine = new String[] {"One", }; // ok, single-line block

  String[] multiLine = new String[] {"One",
    "Two", }; // violation ''}' at column 12 should be on a new line'

  String[] multiLineNewLine = new String[] {"One", "Two",
  }; // ok, right curly brace is on a new line

  Runnable action = () -> {
    doSomething();
  }; // ok, right curly brace is on a new line

  void doSomething() {
  }
}

class Example2 {

  String[] oneLine = new String[] {"One", }; // ok, single-line block

  String[] multiLine = new String[] {"One",
    "Two", }; // ok, right curly brace is on the same line

  String[] multiLineNewLine = new String[] {"One", "Two",
  }; // violation ''}' at column 3 should be on the previous line'

  Runnable action = () -> {
    doSomething();
  }; // violation ''}' at column 3 should be on the previous line'

  void doSomething() {
  }

  String[] extraLine = new String[] {"Three", "Four"}; // ok, single-line block
}

class Example3 {

  String[] oneLine = new String[] {"One", }; // violation 'should be on a new line'

  String[] multiLine = new String[] {"One",
    "Two", }; // violation ''}' at column 12 should be on a new line'

  String[] multiLineNewLine = new String[] {"One", "Two",
  }; // ok, right curly brace is on a new line

  Runnable action = () -> {
    doSomething();
  }; // ok, right curly brace is on a new line

  void doSomething() {
  }
}
